app.post("/api/email-otp/send", async (req, res) => {
  const email = normalizeEmail(req.body?.email);
  if (!email) {
    return res.status(400).json({ ok: false, error: "Enter a valid email address (e.g. you@gmail.com)." });
  }
  if (!EMAIL_OTP_ENABLED) {
    return res.status(503).json({
      ok: false,
      error: "Email OTP is not enabled yet. Please try again later.",
    });
  }

  const now = Date.now();
  const rec = emailOtpStore.get(email) || { sentCount: 0, attempts: 0 };
  if (rec.sentAt && now - rec.sentAt < EMAIL_OTP_COOLDOWN_MS) {
    const wait = Math.ceil((EMAIL_OTP_COOLDOWN_MS - (now - rec.sentAt)) / 1000);
    return res.status(429).json({ ok: false, error: `Please send again after ${wait} seconds.`, retryAfterSeconds: wait });
  }
  if (emailToday() >= EMAIL_OTP_DAILY_CAP) {
    return res.status(429).json({ ok: false, error: "Today's email limit is finished — try again tomorrow." });
  }

  const code = freshOtpCode(email); // 🔐 हर बार नया कोड, पर 10 मिनट तक मान्य
  emailOtpDayCount = emailToday() + 1;
  const sent = await sendEmailOtpCode(email, code);
  if (!sent.ok) {
    console.log(`⚠️ Email OTP fail [${sent.provider}]:`, JSON.stringify(sent.detail || {}).slice(0, 200));
    return res.status(502).json({ ok: false, error: "The email could not be sent — try again shortly." });
  }

  emailOtpStore.set(email, {
    hash: emailOtpHash(email, code),
    expiresAt: now + EMAIL_OTP_TTL_MS,
    attempts: 0,
    sentAt: now,
    sentCount: (rec.sentCount || 0) + 1,
  });

  res.json({
    ok: true,
    provider: sent.provider,
    expiresInSeconds: Math.round(EMAIL_OTP_TTL_MS / 1000),
    devOtp: EMAIL_OTP_PREVIEW ? code : undefined,
    message: `Code sent to ${email} (check the Spam folder too).`,
  });
});

app.post("/api/email-otp/verify", (req, res) => {
  const email = normalizeEmail(req.body?.email);
  const code = String(req.body?.code || "").replace(/\D/g, "");
  if (!email) return res.status(400).json({ ok: false, error: "The email is not valid." });
  if (code.length !== 6) return res.status(400).json({ ok: false, error: "Enter the 6-digit code." });

  const rec = emailOtpStore.get(email) || { attempts: 0, sentCount: 0 };

  // 1) समय-आधारित कोड — पिछले 10 मिनट के किसी भी सेकंड का कोड चलेगा
  //    (सर्वर restart / नई deploy हो जाए, तब भी काम करेगा)
  const timeMatch = isRecentOtpCode(email, code);
  // 2) साथ ही RAM में सेव कोड भी (पुराने तरीके से भेजे गए कोड के लिए)
  const sentMatch =
    Boolean(rec.hash) && Boolean(rec.expiresAt) && Date.now() <= rec.expiresAt && rec.hash === emailOtpHash(email, code);
  if (!timeMatch && !sentMatch) {
    rec.attempts += 1;
    emailOtpStore.set(email, { ...rec, attempts: rec.attempts });
    return res.status(400).json({
      ok: false,
      error: `Code not found! Attempts left: ${Math.max(0, EMAIL_OTP_MAX_ATTEMPTS - rec.attempts)} — send a new code or enter the correct 6 digits.`,
      attemptsLeft: Math.max(0, EMAIL_OTP_MAX_ATTEMPTS - rec.attempts),
    });
  }

  emailOtpStore.delete(email);
  const issued = Date.now();
  const sig = crypto
    .createHmac("sha256", OTP_SECRET)
    .update(`mail|${email}|${issued}`)
    .digest("hex")
    .slice(0, 32);
  res.json({ ok: true, token: `${issued}.${sig}`, email, verifiedAt: issued });
});

// Passwordless auth is performed only on the server after validating the signed email-OTP token.
const usedEmailAuthTokens = new Map();
function claimEmailAuthToken(email, token) {
  const digest = crypto.createHash("sha256").update(`${email}|${token}`).digest("hex");
  const now = Date.now();
  for (const [key, value] of usedEmailAuthTokens) if (value.expiresAt < now) usedEmailAuthTokens.delete(key);
  if (usedEmailAuthTokens.has(digest)) return null;
  usedEmailAuthTokens.set(digest, { expiresAt: now + EMAIL_OTP_TTL_MS, state: "pending" });
  return digest;
}
function finishEmailAuthToken(digest, success) {
  if (!digest) return;
  if (success) usedEmailAuthTokens.set(digest, { expiresAt: Date.now() + EMAIL_OTP_TTL_MS, state: "used" });
  else usedEmailAuthTokens.delete(digest);
}
async function callSupabaseServiceRpc(name, body) {
  if (!WC_SUPABASE_SERVICE_ROLE_KEY) throw new Error("WC_SUPABASE_SERVICE_ROLE_KEY is not configured.");
  const response = await fetch(`${WC_SUPABASE_URL}/rest/v1/rpc/${name}`, {
    method: "POST",
    headers: {
      apikey: WC_SUPABASE_SERVICE_ROLE_KEY,
      Authorization: `Bearer ${WC_SUPABASE_SERVICE_ROLE_KEY}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify(body),
  });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) {
    console.error("Passwordless auth RPC failed:", name, response.status);
    throw new Error("Secure account verification is temporarily unavailable.");
  }
  return data;
}
async function getAccountBoundEmailForLogin(phone) {
  if (!WC_SUPABASE_SERVICE_ROLE_KEY) throw new Error("Secure account lookup is not configured.");
  const headers = {
    apikey: WC_SUPABASE_SERVICE_ROLE_KEY,
    Authorization: `Bearer ${WC_SUPABASE_SERVICE_ROLE_KEY}`,
  };
  const accountsUrl = new URL(`${WC_SUPABASE_URL}/rest/v1/wc_accounts`);
  accountsUrl.searchParams.set("select", "user_id");
  accountsUrl.searchParams.set("phone_norm", `eq.${phone}`);
  accountsUrl.searchParams.set("limit", "1");
  const accountResponse = await fetch(accountsUrl, { headers });
  if (!accountResponse.ok) throw new Error("Secure account verification is temporarily unavailable.");
  const accounts = await accountResponse.json().catch(() => []);
  if (!Array.isArray(accounts) || !accounts.length) return { accountExists: false, email: "" };

  const emailUrl = new URL(`${WC_SUPABASE_URL}/rest/v1/wc_account_emails`);
  emailUrl.searchParams.set("select", "email");
  emailUrl.searchParams.set("phone_norm", `eq.${phone}`);
  emailUrl.searchParams.set("limit", "1");
  const emailResponse = await fetch(emailUrl, { headers });
  if (!emailResponse.ok) throw new Error("Secure account verification is temporarily unavailable.");
  const bindings = await emailResponse.json().catch(() => []);
  const email = Array.isArray(bindings) && bindings.length ? normalizeEmail(bindings[0]?.email) : "";
  return { accountExists: true, email };
}

async function issueLoginOtp(email, purpose = "login") {
  if (!EMAIL_OTP_ENABLED) return { status: 503, body: { ok: false, error: "Email OTP is temporarily unavailable." } };
  const now = Date.now();
  const rec = emailOtpStore.get(email) || { sentCount: 0, attempts: 0 };
  if (rec.sentAt && now - rec.sentAt < EMAIL_OTP_COOLDOWN_MS) {
    const wait = Math.ceil((EMAIL_OTP_COOLDOWN_MS - (now - rec.sentAt)) / 1000);
    return { status: 429, body: { ok: false, error: `Please send again after ${wait} seconds.`, retryAfterSeconds: wait } };
  }
  if (emailToday() >= EMAIL_OTP_DAILY_CAP) {
    return { status: 429, body: { ok: false, error: "Today's email limit is finished — try again tomorrow." } };
  }
  const code = freshOtpCode(email);
  emailOtpDayCount = emailToday() + 1;
  const sent = await sendEmailOtpCode(email, code);
  if (!sent.ok) {
    console.log(`⚠️ Login email OTP fail [${sent.provider}]:`, JSON.stringify(sent.detail || {}).slice(0, 200));
    return { status: 502, body: { ok: false, error: "The email could not be sent — try again shortly." } };
  }
  emailOtpStore.set(email, {
    hash: emailOtpHash(email, code),
    expiresAt: now + EMAIL_OTP_TTL_MS,
    attempts: 0,
    sentAt: now,
    sentCount: (rec.sentCount || 0) + 1,
  });
  return {
    status: 200,
    body: {
      ok: true,
      provider: sent.provider,
      expiresInSeconds: Math.round(EMAIL_OTP_TTL_MS / 1000),
      devOtp: EMAIL_OTP_PREVIEW ? code : undefined,
      message: purpose === "signup" ? "Signup verification code sent to this email." : "Login code sent to the email saved on this account.",
    },
  };
}

async function checkSignupIdentityAvailable(phone, email) {
  if (!WC_SUPABASE_SERVICE_ROLE_KEY) throw new Error("Secure account lookup is not configured.");
  const headers = { apikey: WC_SUPABASE_SERVICE_ROLE_KEY, Authorization: `Bearer ${WC_SUPABASE_SERVICE_ROLE_KEY}` };
  const accountUrl = new URL(`${WC_SUPABASE_URL}/rest/v1/wc_accounts`);
  accountUrl.searchParams.set("select", "user_id");
  accountUrl.searchParams.set("phone_norm", `eq.${phone}`);
  accountUrl.searchParams.set("limit", "1");
  const accountResponse = await fetch(accountUrl, { headers });
  if (!accountResponse.ok) throw new Error("Secure account verification is temporarily unavailable.");
  const accounts = await accountResponse.json().catch(() => []);
  if (Array.isArray(accounts) && accounts.length) return { ok: false, code: "phone_taken", error: "This phone already has an account. Log in with its existing details." };

  const emailUrl = new URL(`${WC_SUPABASE_URL}/rest/v1/wc_account_emails`);
  emailUrl.searchParams.set("select", "phone_norm");
  emailUrl.searchParams.set("email", `eq.${email}`);
  emailUrl.searchParams.set("limit", "1");
  const emailResponse = await fetch(emailUrl, { headers });
  if (!emailResponse.ok) throw new Error("Secure account verification is temporarily unavailable.");
  const bindings = await emailResponse.json().catch(() => []);
  if (Array.isArray(bindings) && bindings.length) return { ok: false, code: "email_taken", error: "This Gmail already exists, please change your email." };
  return { ok: true };
}

app.post("/api/auth/email-otp/send-signup", rateLimit({ windowMs: 60000, max: 6, key: "signup-email-send" }), async (req, res) => {
  const phone = normalizePhone(req.body?.phone);
  const email = normalizeEmail(req.body?.email);
  if (!phone || !email) return res.status(400).json({ ok: false, error: "Enter a valid phone number and Gmail address." });
  try {
    const available = await checkSignupIdentityAvailable(phone, email);
    if (!available.ok) return res.status(409).json(available);
    const result = await issueLoginOtp(email, "signup");
    return res.status(result.status).json(result.body);
  } catch (error) {
    console.error("Signup identity check failed:", String(error?.message || error).slice(0, 180));
    return res.status(503).json({ ok: false, error: "Secure signup verification is temporarily unavailable." });
  }
});

app.post("/api/auth/email-otp/send-login", rateLimit({ windowMs: 60000, max: 6, key: "login-email-send" }), async (req, res) => {
  const phone = normalizePhone(req.body?.phone);
  const requestedEmail = normalizeEmail(req.body?.email);
  if (!phone || !requestedEmail) {
    return res.status(400).json({ ok: false, error: "Enter the registered phone and its saved email." });
  }
  try {
    const bound = await getAccountBoundEmailForLogin(phone);
    if (!bound.accountExists) {
      return res.status(404).json({ ok: false, code: "account_not_found", error: "Account not found. Please sign up." });
    }
    if (!bound.email) {
      return res.status(409).json({ ok: false, code: "email_unbound", error: "This older account has no locked email. It needs safe recovery before email-OTP login." });
    }
    if (requestedEmail !== bound.email) {
      return res.status(403).json({ ok: false, code: "email_mismatch", error: "This phone and email do not match. Enter the exact email used at signup." });
    }
    const result = await issueLoginOtp(bound.email);
    return res.status(result.status).json(result.body);
  } catch (error) {
    console.error("Bound login-email lookup failed:", String(error?.message || error).slice(0, 180));
    return res.status(503).json({ ok: false, error: "Secure account verification is temporarily unavailable." });
  }
});

function authRandomPin() {
  return String(crypto.randomInt(10000000, 100000000));
}
app.post("/api/auth/email-login", rateLimit({ windowMs: 60000, max: 10, key: "email-login" }), async (req, res) => {
  const email = normalizeEmail(req.body?.email);
  const phone = normalizePhone(req.body?.phone);
  const token = String(req.body?.token || "");
  if (!email || !phone || !emailOtpTokenValid(email, token)) {
    return res.status(401).json({ ok: false, error: "Email verification expired. Request and verify a fresh code." });
  }
  const tokenId = claimEmailAuthToken(email, token);
  if (!tokenId) return res.status(409).json({ ok: false, error: "This verified email code was already used. Request a new code." });
  try {
    const sessionPin = authRandomPin();
    const result = await callSupabaseServiceRpc("wc_passwordless_login", {
      p_phone: phone, p_email: email, p_pin: sessionPin,
    });
    if (!result?.ok || !result?.account) {
      finishEmailAuthToken(tokenId, false);
      const message = result?.code === "email_mismatch"
        ? `This number belongs to a different saved Gmail (${result.masked || "hidden"}). Use that Gmail.`
        : result?.code === "email_unbound"
          ? "This older account has no locked Gmail yet. Contact support to verify it safely."
          : result?.code === "banned"
            ? "This account is not available. Contact support."
            : result?.error || "No matching account was found for this phone and Gmail.";
      return res.status(403).json({ ok: false, code: result?.code, error: message });
    }
    finishEmailAuthToken(tokenId, true);
    return res.json({ ok: true, account: result.account, sessionPin, via: "email_otp" });
  } catch (error) {
    finishEmailAuthToken(tokenId, false);
    return res.status(503).json({ ok: false, error: String(error?.message || "Secure login is temporarily unavailable.") });
  }
});
app.post("/api/auth/email-signup", rateLimit({ windowMs: 60000, max: 8, key: "email-signup" }), async (req, res) => {
  const email = normalizeEmail(req.body?.email);
  const phone = normalizePhone(req.body?.phone);
  const token = String(req.body?.token || "");
  const name = String(req.body?.name || "").trim().slice(0, 60);
  const avatar = String(req.body?.avatar || "🧑‍🚀").slice(0, 16);
  if (!email || !phone || !name) return res.status(400).json({ ok: false, error: "Enter a valid phone, Gmail, and name." });
  if (!emailOtpTokenValid(email, token)) return res.status(401).json({ ok: false, error: "Email verification expired. Request and verify a fresh code." });
  const tokenId = claimEmailAuthToken(email, token);
  if (!tokenId) return res.status(409).json({ ok: false, error: "This verified email code was already used. Request a new code." });
  try {
    const sessionPin = authRandomPin();
    const result = await callSupabaseServiceRpc("wc_create_account_bound", {
      p_phone: phone, p_name: name, p_pin: sessionPin, p_avatar: avatar, p_email: email,
    });
    if (result?.already_exists) {
      finishEmailAuthToken(tokenId, false);
      return res.status(409).json({ ok: false, already_exists: true, error: "This phone already has an account. Go to login and verify its saved Gmail." });
    }
    if (!result?.ok || !result?.account) {
      finishEmailAuthToken(tokenId, false);
      return res.status(400).json({ ok: false, code: result?.code, error: result?.error || "Account creation could not be completed." });
    }
    finishEmailAuthToken(tokenId, true);
    return res.json({ ok: true, account: result.account, sessionPin, via: "email_otp_signup" });
  } catch (error) {
    finishEmailAuthToken(tokenId, false);
    return res.status(503).json({ ok: false, error: String(error?.message || "Secure signup is temporarily unavailable.") });
  }
});

// Secure one-time legacy email binding: OTP token is checked on the server before calling the locked-email RPC.
app.post("/api/email-otp/bind-account", async (req, res) => {
  const email = normalizeEmail(req.body?.email);
  const phone = normalizePhone(req.body?.phone);
  const pin = String(req.body?.pin || "").trim();
  const token = String(req.body?.token || "");
  if (!email || !phone || pin.length < 4 || pin.length > 32) {
    return res.status(400).json({ ok: false, error: "Valid phone, email, and PIN are required." });
  }
  if (!emailOtpTokenValid(email, token)) {
    return res.status(401).json({ ok: false, code: "email_otp_required", error: "Verify a fresh email OTP first." });
  }
  try {
    const upstream = await fetch(`${WC_SUPABASE_URL}/rest/v1/rpc/wc_save_account_email`, {
      method: "POST",
      headers: { apikey: WC_SUPABASE_ANON_KEY, Authorization: `Bearer ${WC_SUPABASE_ANON_KEY}`, "Content-Type": "application/json" },
      body: JSON.stringify({ p_phone: phone, p_pin: pin, p_email: email }),
    });
    const data = await upstream.json().catch(() => ({}));
    return res.status(upstream.status).json(data);
  } catch (error) {
    console.error("Email binding RPC failed:", String(error?.message || error).slice(0, 180));
    return res.status(502).json({ ok: false, error: "Secure email binding is temporarily unavailable." });
  }
});

